    fun copy(source: PsiElementBase, initialize: (PsiElementBase) -> Unit): PsiElementBase {
        val allocate = factories[source::class]
            ?: throw UnsupportedOperationException("Missing concrete Kotlin PSI clone metadata: ${source::class}")
        val target = allocate()
        check(target !== source && target::class == source::class)
        initialize(target)
        return target
    }
